'use client';

import { useEffect, useId, useRef, useState, type CSSProperties } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import type { Aim } from './_parts/aim';
import { DemoBand } from './_parts/demo-band';
import { DEFAULT_HUE } from './_parts/hue';
import { landTransitions } from './_parts/loops';
import { watchShowing } from './_parts/showing';
import { useCells } from './_parts/use-cells';

const DEFAULT_CELL = 40;

const MIN_CELL = 8;

/**
 * A line is one device pixel wide and lies wholly inside its cell: the path runs along the top and
 * left edges, shifted in by half its own width, so it never straddles two pixels.
 */
const LINE_STYLE: CSSProperties = {
  strokeWidth: 'var(--hairline, 1px)',
  transform:
    'translate(calc(var(--hairline, 1px) / 2), calc(var(--hairline, 1px) / 2))',
};

/** Five dashes to a cell, so a dashed line runs on from one cell to the next without a seam. */
const DASHES_PER_CELL = 5;

const DASH_PARTS = DASHES_PER_CELL * 2;

const FADE_MASK =
  '[mask-image:radial-gradient(ellipse_at_center,black_30%,transparent_78%)]';

/** How strongly a lit cell wears the hue. Text sits above the grid, so it stays a tint. */
const LIT_FILL = 'color-mix(in oklab, currentColor 16%, transparent)';

/**
 * A lit cell is a box laid over the pattern. A box that fades its opacity on its own layer is
 * composited, where a shape inside the drawing would repaint the grid on every frame of its fade.
 * The layer is kept between fades, so starting or ending one repaints nothing either.
 */
const LIT_CELL =
  'absolute top-px left-px opacity-0 transition-opacity duration-700 ease-(--ease-out-strong) will-change-[opacity]';

/** Where the four lit cells rest, across and down the box. */
const RESTS: Aim[] = [
  { x: 0.2, y: 0.32 },
  { x: 0.42, y: 0.7 },
  { x: 0.63, y: 0.24 },
  { x: 0.82, y: 0.62 },
];

/** A cell fades out, lands on its new place and fades in, then the next one takes its turn. */
const FADE_MS = 700;

const REST_MS = 1100;

/** A new place is drawn inside this margin, so a lit cell is never cut by the edge of the box. */
const EDGE_MARGIN = 0.06;

const BOTH_MARGINS = EDGE_MARGIN * 2;

const PLACE_ROOM = 1 - BOTH_MARGINS;

const PLACE_TRIES = 8;

const RADIANS_PER_DEGREE = Math.PI / 180;

type Place = {
  column: number;
  row: number;
};

function dashesOf(isDashed: boolean, cell: number) {
  if (!isDashed) {
    return undefined;
  }
  const dash = cell / DASH_PARTS;
  return `${dash} ${dash}`;
}

/**
 * The cell under a point of the box. The grid is twice as wide as the box, starts half a box to
 * its left and leans around its own middle, so the point is brought back into the grid first.
 */
function cellAt(
  host: HTMLElement,
  aim: Aim,
  cell: number,
  skew: number
): Place {
  const width = host.clientWidth;
  const height = host.clientHeight;
  const halfWidth = width / 2;
  const halfHeight = height / 2;
  const x = aim.x * width;
  const y = aim.y * height;
  const radians = skew * RADIANS_PER_DEGREE;
  const lean = Math.tan(radians);
  const fromMiddle = y - halfHeight;
  const leaned = fromMiddle * lean;
  const fromGridEdge = x + halfWidth;
  const along = fromGridEdge - leaned;
  const column = Math.floor(along / cell);
  const row = Math.floor(y / cell);
  return { column, row };
}

function litStyleOf(side: number): CSSProperties {
  return { width: side, height: side, backgroundColor: LIT_FILL };
}

function put(square: HTMLElement, place: Place, cell: number) {
  const x = place.column * cell;
  const y = place.row * cell;
  square.style.transform = `translate(${x}px, ${y}px)`;
}

function show(square: HTMLElement) {
  square.style.opacity = '1';
}

function hide(square: HTMLElement) {
  square.style.opacity = '0';
}

function isSamePlace(first: Place, second: Place) {
  const isSameColumn = first.column === second.column;
  const isSameRow = first.row === second.row;
  return isSameColumn && isSameRow;
}

function shareWithinMargin() {
  const share = Math.random() * PLACE_ROOM;
  return EDGE_MARGIN + share;
}

type Trade = {
  host: HTMLElement;
  squares: HTMLElement[];
  places: Place[];
  cell: number;
  skewOf: () => number;
};

/** A place no lit cell holds. After a few unlucky draws the last one is taken as it is. */
function freePlaceOf(trade: Trade) {
  let place: Place = { column: 0, row: 0 };
  for (let attempt = 0; attempt < PLACE_TRIES; attempt += 1) {
    const aim = { x: shareWithinMargin(), y: shareWithinMargin() };
    const candidate = cellAt(trade.host, aim, trade.cell, trade.skewOf());
    const isTaken = trade.places.some((taken) => isSamePlace(taken, candidate));
    place = candidate;
    if (!isTaken) {
      return place;
    }
  }
  return place;
}

function settle(trade: Trade) {
  trade.squares.forEach((square, index) => {
    const rest = RESTS[index];
    if (!rest) {
      return;
    }
    const place = cellAt(trade.host, rest, trade.cell, trade.skewOf());
    trade.places[index] = place;
    put(square, place, trade.cell);
    show(square);
  });
}

/**
 * The lit cells trade places while the grid shows: one timer, and an opacity transition between
 * two of its ticks. Hidden, the timer is gone and every cell is put back in sight where it stands,
 * at once.
 */
function tradeWhileShowing(trade: Trade) {
  let turn = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;

  function land() {
    const square = trade.squares[turn];
    const place = freePlaceOf(trade);
    trade.places[turn] = place;
    if (square) {
      put(square, place, trade.cell);
      show(square);
    }
    const next = turn + 1;
    turn = next % trade.squares.length;
    timer = setTimeout(leave, REST_MS);
  }

  function leave() {
    const square = trade.squares[turn];
    if (square) {
      hide(square);
    }
    timer = setTimeout(land, FADE_MS);
  }

  function stop() {
    clearTimeout(timer);
    timer = undefined;
    trade.squares.forEach(show);
    landTransitions(trade.host);
  }

  const stopWatching = watchShowing(trade.host, (isShowing) => {
    if (isShowing) {
      timer = setTimeout(leave, REST_MS);
      return;
    }
    stop();
  });

  return () => {
    stopWatching();
    stop();
  };
}

export type GridPatternProps = {
  className?: string;
  /** Any colour token, such as `var(--primary)` or `var(--series-2)`. The lit cells wear it. */
  hue?: string;
  /** The side of a cell, in pixels. */
  size?: number;
  dashed?: boolean;
  /** How far the grid leans, in degrees. Keep it between -30 and 30. */
  skew?: number;
  /** Fades the grid out towards the edges of the box. */
  fade?: boolean;
};

/**
 * A crisp grid of hairlines in the border colour, drawn by one SVG pattern on whole pixels, with
 * four cells lit in the hue that trade places every few seconds. The lines can be dashed, the grid
 * can lean and fade out towards its edges. It fills its parent, which must be positioned. Under
 * reduced motion the four cells stay where they are.
 */
export function GridPattern({
  className,
  hue = DEFAULT_HUE,
  size = DEFAULT_CELL,
  dashed = false,
  skew = 0,
  fade = false,
}: GridPatternProps) {
  const patternId = useId();
  const hostRef = useRef<HTMLDivElement>(null);
  const skewRef = useRef(skew);
  const shouldReduceMotion = usePrefersReducedMotion();
  const cell = Math.max(MIN_CELL, size);
  const { columns, rows } = useCells(hostRef, cell);
  const inner = cell - 1;

  useEffect(() => {
    skewRef.current = skew;
  }, [skew]);

  useEffect(() => {
    const host = hostRef.current;
    const hasCells = columns > 0 && rows > 0;
    if (!host || !hasCells) {
      return;
    }
    const lit = host.querySelectorAll<HTMLElement>('[data-lit]');
    const squares = Array.from(lit);
    const trade: Trade = {
      host,
      squares,
      places: [],
      cell,
      skewOf: () => skewRef.current,
    };
    settle(trade);
    if (shouldReduceMotion) {
      return;
    }
    return tradeWhileShowing(trade);
  }, [columns, rows, cell, shouldReduceMotion]);

  return (
    <div
      ref={hostRef}
      aria-hidden='true'
      style={{ color: hue }}
      className={cn(
        'pointer-events-none absolute inset-0 overflow-hidden transition-colors duration-500',
        fade && FADE_MASK,
        className
      )}
    >
      <div
        style={{ transform: `skewX(${skew}deg)` }}
        className='absolute -inset-x-1/2 inset-y-0 transition-transform duration-500 ease-(--ease-out-strong)'
      >
        <svg aria-hidden='true' className='absolute inset-0 size-full'>
          <defs>
            <pattern
              id={patternId}
              width={cell}
              height={cell}
              patternUnits='userSpaceOnUse'
            >
              <path
                d={`M${cell} 0H0V${cell}`}
                fill='none'
                stroke='currentColor'
                strokeDasharray={dashesOf(dashed, cell)}
                shapeRendering='crispEdges'
                style={LINE_STYLE}
                className='text-border'
              />
            </pattern>
          </defs>
          <rect width='100%' height='100%' fill={`url(#${patternId})`} />
        </svg>
        {RESTS.map((rest) => (
          <div
            key={rest.x}
            data-lit=''
            style={litStyleOf(inner)}
            className={LIT_CELL}
          />
        ))}
      </div>
    </div>
  );
}

/** A lean that shows the option without bending the grid out of the band. */
const DEMO_SKEW = -14;

function skewOf(isLeaning: boolean) {
  if (isLeaning) {
    return DEMO_SKEW;
  }
  return 0;
}

function labelOf(isLeaning: boolean) {
  if (isLeaning) {
    return 'Level the grid';
  }
  return 'Tilt the grid';
}

export default function Background07() {
  const [isLeaning, setIsLeaning] = useState(false);
  const label = labelOf(isLeaning);

  return (
    <DemoBand
      title='A grid where four cells trade places'
      background={<GridPattern skew={skewOf(isLeaning)} fade />}
    >
      <Button onClick={() => setIsLeaning((current) => !current)}>
        <Swap swapKey={label}>{label}</Swap>
      </Button>
    </DemoBand>
  );
}

import { landTransitions } from './loops';
import { watchPointer } from './pointer';
import { watchShowing } from './showing';

/** A place in a box: from 0 at its left or top edge to 1 at its right or bottom edge. */
export type Aim = {
  x: number;
  y: number;
};

export type AimOptions = {
  /** The round the aim walks while no pointer leads it. The first one is where it rests. */
  waypoints: readonly Aim[];
  /** Milliseconds between two waypoints. */
  stepMs: number;
  /** Milliseconds of the glide to a waypoint: `stepMs` for a walk without a rest, less for one with rests. */
  glideMs: number;
  /** Milliseconds for the aim to reach a pointer. */
  followMs: number;
  isInteractive: boolean;
  /**
   * Sends the picture to `aim` over `durationMs`. A CSS transition carries it there, so nothing is
   * computed on the way and no frame is asked for.
   */
  onAim: (aim: Aim, durationMs: number, isFollowing: boolean) => void;
};

function idle() {}

/**
 * An aim that walks from waypoint to waypoint while the host shows, and goes to the pointer while
 * one is over the host. One timer steps the walk. Hidden, the timer is gone and the glide in flight
 * lands at once where it was going. The function returned ends the watch.
 */
export function watchAim(host: HTMLElement, options: AimOptions) {
  const { waypoints, stepMs, glideMs, followMs, isInteractive, onAim } =
    options;
  const first = waypoints[0];
  if (!first) {
    return idle;
  }
  let index = 0;
  let latest = first;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let isShowing = false;
  let stopPointer = idle;

  function clearStep() {
    clearTimeout(timer);
    timer = undefined;
  }

  function stepOn() {
    const next = index + 1;
    index = next % waypoints.length;
    latest = waypoints[index] ?? first;
    onAim(latest, glideMs, false);
    timer = setTimeout(stepOn, stepMs);
  }

  function follow(x: number, y: number) {
    clearStep();
    const across = x / host.offsetWidth;
    const down = y / host.offsetHeight;
    latest = { x: across, y: down };
    onAim(latest, followMs, true);
  }

  function release() {
    if (isShowing) {
      stepOn();
    }
  }

  function show() {
    isShowing = true;
    if (isInteractive) {
      stopPointer = watchPointer(host, follow, release);
    }
    stepOn();
  }

  function hide() {
    isShowing = false;
    clearStep();
    stopPointer();
    stopPointer = idle;
    onAim(latest, 0, false);
    landTransitions(host);
  }

  const stopShowing = watchShowing(host, (isNowShowing) => {
    if (isNowShowing) {
      show();
      return;
    }
    hide();
  });

  return () => {
    stopShowing();
    hide();
  };
}

import { useId, type ReactNode, type Ref } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

type BandAlign = 'center' | 'end';

const ALIGNMENTS: Record<BandAlign, string> = {
  center: 'justify-center',
  end: 'justify-end pb-10',
};

type DemoBandProps = {
  ref?: Ref<HTMLElement>;
  title: string;
  /** The background under test. It fills the band, behind the headline and the actions. */
  background: ReactNode;
  /** `end` sets the headline at the foot of the band and leaves its middle to the background. */
  align?: BandAlign;
  children: ReactNode;
};

/**
 * The band every background is shown in: the page colour, a headline in the foreground colour and
 * the actions laid straight over the background, to prove that text stays readable above it.
 */
export function DemoBand({
  ref,
  title,
  background,
  align = 'center',
  children,
}: DemoBandProps) {
  const titleId = useId();

  return (
    <section
      ref={ref}
      aria-labelledby={titleId}
      className={cn(
        'bg-background @container relative isolate flex h-90 w-full flex-col items-center overflow-hidden rounded-xl',
        ALIGNMENTS[align]
      )}
    >
      {background}
      <div className='relative flex max-w-lg flex-col items-center gap-5 px-6 text-center'>
        <h3
          id={titleId}
          className='text-2xl font-semibold text-balance @lg:text-3xl'
        >
          {title}
        </h3>
        <div className='flex flex-wrap items-center justify-center gap-2'>
          {children}
        </div>
      </div>
    </section>
  );
}

'use client';

import { useState } from 'react';

/** A background wears one hue: the brand unless it is told otherwise. */
export const DEFAULT_HUE = 'var(--primary)';

/** The brand first, then the series hues that differ from it. */
const DEMO_HUES = [
  DEFAULT_HUE,
  'var(--series-2)',
  'var(--series-3)',
  'var(--series-4)',
  'var(--series-5)',
];

/** The hue of a demo, and the step to the next one, to show a background in each hue it accepts. */
export function useHueCycle() {
  const [index, setIndex] = useState(0);
  const hue = DEMO_HUES[index] ?? DEFAULT_HUE;

  function nextHue() {
    setIndex((current) => {
      const next = current + 1;
      return next % DEMO_HUES.length;
    });
  }

  return { hue, nextHue };
}

import { watchShowing } from './showing';

function hold(animations: Animation[]) {
  for (const animation of animations) {
    animation.pause();
  }
}

function resume(animations: Animation[]) {
  for (const animation of animations) {
    animation.play();
  }
}

function cancel(animations: Animation[]) {
  for (const animation of animations) {
    animation.cancel();
  }
}

/**
 * Lands every transition still running under `host` at its end value. A transition asks for frames
 * until it ends, on screen or not, and a host that stops showing must ask for none.
 */
export function landTransitions(host: Element) {
  const animations = host.getAnimations({ subtree: true });
  for (const animation of animations) {
    const isTransition = animation instanceof CSSTransition;
    if (isTransition) {
      animation.finish();
    }
  }
}

/**
 * Endless animations that run only while their host shows. Off screen and in a hidden tab they are
 * paused: they keep their place and ask for no frame. They start paused, and `onShowing` is told
 * each time the host starts or stops showing. The function returned removes them.
 */
export function runWhileShowing(
  host: Element,
  animations: Animation[],
  onShowing?: (isShowing: boolean) => void
) {
  hold(animations);
  const stopWatching = watchShowing(host, (isShowing) => {
    onShowing?.(isShowing);
    if (isShowing) {
      resume(animations);
      return;
    }
    hold(animations);
  });
  return () => {
    stopWatching();
    cancel(animations);
  };
}

export type Point = {
  x: number;
  y: number;
};

export function clamp(value: number, low: number, high: number) {
  const raised = Math.max(low, value);
  return Math.min(high, raised);
}

/** How much of the way left is covered in `seconds`: the same glide whatever the frame rate. */
export function shareOf(seconds: number, easeSeconds: number) {
  const ratio = seconds / easeSeconds;
  const decay = Math.exp(-ratio);
  return 1 - decay;
}

export function towards(from: number, to: number, share: number) {
  const gap = to - from;
  const step = gap * share;
  return from + step;
}

/** From 0 at `low` to 1 at `high`, leaving and arriving without a corner. */
export function smoothstep(low: number, high: number, value: number) {
  const span = high - low;
  const offset = value - low;
  const raw = offset / span;
  const share = clamp(raw, 0, 1);
  const doubled = 2 * share;
  const curve = 3 - doubled;
  const squared = share * share;
  return squared * curve;
}

/** The damping that brings a spring of this stiffness to its target without passing it. */
export function dampingOf(stiffness: number) {
  const root = Math.sqrt(stiffness);
  return 2 * root;
}

/**
 * The speed of a spring one step later. The caller then moves the value by that speed over the
 * same step, so the value follows its target and settles on it.
 */
export function springSpeedOf(
  gap: number,
  speed: number,
  stiffness: number,
  damping: number,
  seconds: number
) {
  const pull = gap * stiffness;
  const drag = speed * damping;
  const push = pull - drag;
  const gain = push * seconds;
  return speed + gain;
}

import type { Point } from './math';

/**
 * Where a point of the window falls inside `host`, in the pixels of its own box, or null when it
 * falls outside. A host that an ancestor scales still answers in its own pixels.
 */
export function placeIn(
  host: HTMLElement,
  clientX: number,
  clientY: number
): Point | null {
  const box = host.getBoundingClientRect();
  const isEmpty = box.width === 0 || box.height === 0;
  if (isEmpty) {
    return null;
  }
  const isInsideX = clientX >= box.left && clientX <= box.right;
  const isInsideY = clientY >= box.top && clientY <= box.bottom;
  if (!isInsideX || !isInsideY) {
    return null;
  }
  const scaleX = host.offsetWidth / box.width;
  const scaleY = host.offsetHeight / box.height;
  const offsetX = clientX - box.left;
  const offsetY = clientY - box.top;
  const x = offsetX * scaleX;
  const y = offsetY * scaleY;
  return { x, y };
}

/** Where the centre of `element` falls inside `host`, or null when it falls outside. */
export function centreIn(host: HTMLElement, element: Element) {
  const box = element.getBoundingClientRect();
  const halfWidth = box.width / 2;
  const halfHeight = box.height / 2;
  const centreX = box.left + halfWidth;
  const centreY = box.top + halfHeight;
  return placeIn(host, centreX, centreY);
}

/**
 * Follows a pointer that can hover, from the window: content laid over a background takes the
 * pointer events of its own box, so a listener on the background would go blind under a headline.
 * The place is read once a frame at most, and only on a frame where the pointer moved. `onMove`
 * gets the place inside `host`; `onLeave` is called once when the pointer goes out of it. The
 * function returned ends the watch, and lets go of a pointer that was still over the host.
 */
export function watchPointer(
  host: HTMLElement,
  onMove: (x: number, y: number) => void,
  onLeave: () => void
) {
  let clientX = 0;
  let clientY = 0;
  let frame = 0;
  let isOver = false;

  function leave() {
    if (!isOver) {
      return;
    }
    isOver = false;
    onLeave();
  }

  function read() {
    frame = 0;
    const place = placeIn(host, clientX, clientY);
    if (!place) {
      leave();
      return;
    }
    isOver = true;
    onMove(place.x, place.y);
  }

  function onPointerMove(event: PointerEvent) {
    const isTouch = event.pointerType === 'touch';
    if (isTouch) {
      return;
    }
    clientX = event.clientX;
    clientY = event.clientY;
    const isReadComing = frame !== 0;
    if (isReadComing) {
      return;
    }
    frame = requestAnimationFrame(read);
  }

  function onPointerGone() {
    cancelAnimationFrame(frame);
    frame = 0;
    leave();
  }

  const root = document.documentElement;
  window.addEventListener('pointermove', onPointerMove, { passive: true });
  root.addEventListener('pointerleave', onPointerGone, { passive: true });

  return () => {
    window.removeEventListener('pointermove', onPointerMove);
    root.removeEventListener('pointerleave', onPointerGone);
    onPointerGone();
  };
}

/**
 * A background sits behind content for as long as the page is open, so everything it runs hangs on
 * this answer: its box touches the screen and the tab is the one looked at. `onChange` is called
 * each time the answer changes, starting from "not showing". The function returned ends the watch.
 */
export function watchShowing(
  element: Element,
  onChange: (isShowing: boolean) => void
) {
  let isOnScreen = false;
  let wasShowing = false;

  function report() {
    const isTabShown = document.visibilityState === 'visible';
    const isShowing = isOnScreen && isTabShown;
    if (isShowing === wasShowing) {
      return;
    }
    wasShowing = isShowing;
    onChange(isShowing);
  }

  function onCrossing(entries: IntersectionObserverEntry[]) {
    const latest = entries.at(-1);
    if (!latest) {
      return;
    }
    isOnScreen = latest.isIntersecting;
    report();
  }

  const observer = new IntersectionObserver(onCrossing);
  observer.observe(element);
  document.addEventListener('visibilitychange', report);

  return () => {
    observer.disconnect();
    document.removeEventListener('visibilitychange', report);
  };
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

export type Cells = {
  columns: number;
  rows: number;
};

const NO_CELLS: Cells = { columns: 0, rows: 0 };

function cellsOf(element: HTMLElement, cell: number): Cells {
  const side = Math.max(1, cell);
  const across = element.clientWidth / side;
  const down = element.clientHeight / side;
  const columns = Math.ceil(across);
  const rows = Math.ceil(down);
  return { columns, rows };
}

function keptIfSame(current: Cells, next: Cells) {
  const hasSameColumns = current.columns === next.columns;
  const hasSameRows = current.rows === next.rows;
  if (hasSameColumns && hasSameRows) {
    return current;
  }
  return next;
}

/**
 * How many cells of `cell` pixels it takes to cover the element, counted again when its box
 * changes. Both counts are 0 until the box has been measured. The state only changes when a count
 * does, so a resize that stays inside the same cells renders nothing again.
 */
export function useCells<Target extends HTMLElement>(
  ref: RefObject<Target | null>,
  cell: number
) {
  const [cells, setCells] = useState(NO_CELLS);

  useEffect(() => {
    const element = ref.current;
    if (!element) {
      return;
    }
    const measured = element;

    function count() {
      const next = cellsOf(measured, cell);
      setCells((current) => keptIfSame(current, next));
    }

    const observer = new ResizeObserver(count);
    observer.observe(measured);
    return () => observer.disconnect();
  }, [ref, cell]);

  return cells;
}
